import * as T from './assets/three.module.js';
import {OrbitControls} from './assets/OrbitControls.js';
const $=s=>document.querySelector(s);
const movements=[
{title:'Сгибание локтя',region:'Верхняя конечность',desc:'Как предплечье приближается к плечу — и почему бицепс работает не один.',joint:'Локтевой сустав',plane:'Сагиттальная',max:130,labels:['РАЗГИБАНИЕ','СГИБАНИЕ'],active:/biceps brachii|brachialis|brachioradialis/i,antagonist:/triceps brachii/i,roles:[['Бицепс и плечевая мышца','Агонисты · сгибают предплечье','Плечевая мышца сгибает локоть при любом положении предплечья. Бицепс также помогает повернуть ладонь вверх.'],['Трёхглавая мышца плеча','Антагонист · разгибает локоть','При подъёме уступает сгибателям. При опускании груза сгибатели могут удлиняться под нагрузкой, контролируя движение.']],tendon:[['Сухожилие бицепса','Передаёт усилие лучевой кости','Соединяет бицепс с бугристостью лучевой кости. Мышца создаёт тягу, а сухожилие передаёт её кости.'],['Сухожилие трицепса','Прикрепляется к локтевому отростку','Передаёт разгибающее усилие. Связки удерживают сустав; они не сокращаются как мышцы.']],steps:[['Сгибание','Сгибатели создают момент силы вокруг локтя. Предплечье поворачивается, кисть движется к плечу.'],['Контролируемое возвращение','При удержании груза бицепс и плечевая мышца тормозят разгибание, работая эксцентрически.']]},
{title:'Отведение плеча',region:'Плечевой пояс',desc:'Подъём руки в сторону: движение плечевой кости и согласованная работа лопатки.',joint:'Плечевой комплекс',plane:'Фронтальная',max:90,labels:['РУКА ВНИЗУ','ОТВЕДЕНИЕ'],active:/deltoid|supraspinatus/i,antagonist:/pectoralis major|latissimus dorsi/i,roles:[['Дельтовидная и надостная','Агонисты · поднимают руку','Надостная мышца участвует в начале и продолжении отведения. Средняя часть дельтовидной создаёт значительную часть подъёмного усилия.'],['Вращательная манжета','Стабилизирует головку плечевой кости','Надостная, подостная, малая круглая и подлопаточная удерживают головку в суставной впадине.']],tendon:[['Сухожилия манжеты','Стабильность при движении','Охватывают головку плечевой кости и передают тягу мышц. Надостное сухожилие проходит под акромионом.'],['Лопатка и её мышцы','Согласованный подъём','Передняя зубчатая и трапециевидная вращают лопатку. В анимации показано только упрощённое движение руки.']],steps:[['Подъём руки','Плечевая кость отводится. Вращательная манжета помогает удерживать головку кости в суставе.'],['Движение лопатки','Лопатка вращается вверх вместе с подъёмом руки. Её вклад меняется по ходу движения и зависит от нагрузки.']]},
{title:'Сгибание колена',region:'Нижняя конечность',desc:'Как голень движется назад и какие структуры направляют движение коленного сустава.',joint:'Коленный сустав',plane:'Сагиттальная',max:110,labels:['РАЗГИБАНИЕ','СГИБАНИЕ'],active:/biceps femoris|semitendinosus|semimembranosus/i,antagonist:/rectus femoris|vastus/i,roles:[['Задняя группа бедра','Агонисты · сгибают колено','Двуглавая, полусухожильная и полуперепончатая мышцы тянут голень назад. Большинство также разгибает бедро.'],['Четырёхглавая мышца','Антагонист · разгибает колено','При сгибании без нагрузки её длина увеличивается. Икроножная мышца тоже может помогать сгибанию колена.']],tendon:[['Сухожилия задней группы','Тяга к костям голени','Двуглавая мышца прикрепляется преимущественно к головке малоберцовой кости; медиальные мышцы — к большеберцовой.'],['Крестообразные связки','Направляют и ограничивают сдвиг','Связки не являются сухожилиями: они соединяют кости. Вместе с менисками помогают стабилизировать колено.']],steps:[['Голень движется назад','Задняя группа бедра создаёт сгибающий момент. Показан вариант со свободной голенью, без опоры стопой.'],['Скольжение и вращение','Реальное колено сочетает перекатывание, скольжение и небольшую ротацию. Модель упрощает их до одной оси.']]},
{title:'Подъём на носок',region:'Голень и стопа',desc:'Подошвенное сгибание: как мышцы голени через ахиллово сухожилие двигают стопу.',joint:'Голеностопный',plane:'Сагиттальная',max:40,labels:['НЕЙТРАЛЬНО','СГИБАНИЕ СТОПЫ'],active:/gastrocnemius|soleus/i,antagonist:/tibialis anterior/i,roles:[['Икроножная и камбаловидная','Агонисты · подошвенное сгибание','Вместе образуют трёхглавую мышцу голени. Камбаловидная работает при разогнутом и согнутом колене.'],['Передняя большеберцовая','Антагонист · тыльное сгибание','Поднимает передний отдел стопы. При опускании пятки мышцы задней группы могут контролировать движение под нагрузкой.']],tendon:[['Ахиллово сухожилие','Передаёт тягу пяточной кости','Объединяет усилие икроножной и камбаловидной мышц. Упругие свойства позволяют запасать и возвращать часть энергии шага.'],['Опора на передний отдел стопы','Пятка поднимается при опоре','В реальном подъёме стопа опирается на пол. Здесь показано направление подошвенного сгибания свободной стопы.']],steps:[['Тяга за пяточную кость','Мышцы голени натягивают ахиллово сухожилие. В голеностопе возникает момент подошвенного сгибания.'],['С опорой и без неё','При опоре это движение поднимает пятку и тело. В модели стопа движется без контакта с полом.']]}
];
let index=0,phase=0,amount=0,playing=false,speed=1,direction=1,layer='muscular';
const meshes=[];let renderer,scene,camera,controls,ready=false;
function role(title,sub,body,n){return `<div class="role"><i class="role-dot ${n?'second':''}"></i><div><b>${title}</b>${sub?`<small>${sub}</small>`:''}<p>${body}</p></div></div>`}
function renderLesson(){const m=movements[index];$('#movementTitle').textContent=m.title;$('#movementDescription').textContent=m.desc;$('#lessonNumber').textContent=`0${index+1} / 04`;$('#playTitle').textContent=m.title;$('#mechanics').innerHTML=`<div><b>${m.joint}</b><span>СУСТАВ</span></div><div><b>${m.plane}</b><span>ПЛОСКОСТЬ</span></div>`;$('#phaseContent').innerHTML=phase===0?m.steps.map((r,n)=>role(r[0],'',r[1],n)).join(''):(phase===1?m.roles:m.tendon).map((r,n)=>role(...r,n)).join('');document.querySelectorAll('[data-phase]').forEach(b=>b.classList.toggle('active',+b.dataset.phase===phase));document.querySelectorAll('.movement').forEach((b,n)=>b.classList.toggle('active',index===n));const labels=$('.timeline-label').children;labels[0].textContent=m.labels[0];labels[2].textContent=m.labels[1];updateProgress();updateMaterials();}
function choose(n){index=(n+movements.length)%movements.length;amount=0;playing=false;direction=1;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Запустить анимацию');$('#selection').hidden=true;renderLesson();pose();}
$('#movementList').innerHTML=movements.map((m,n)=>`<button class="movement" data-index="${n}"><span class="number">0${n+1}</span><span><b>${m.title}</b><small>${m.region}</small></span><span class="arrow">↗</span></button>`).join('');
document.querySelectorAll('.movement').forEach(b=>b.onclick=()=>choose(+b.dataset.index));$('#prev').onclick=()=>choose(index-1);$('#next').onclick=()=>choose(index+1);document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=+b.dataset.phase;renderLesson()});
function updateProgress(){$('#progress').value=amount*100;$('#progress').style.setProperty('--progress',`${amount*100}%`);$('#angle').textContent=`${Math.round(amount*movements[index].max)}°`;$('#phaseLabel').textContent=amount<.02?'Исходное положение':direction>0?'Фаза движения':'Возвращение';}
$('#progress').oninput=e=>{playing=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Запустить анимацию');amount=+e.target.value/100;updateProgress();pose()};$('#play').onclick=()=>{playing=!playing;if(amount>=1)direction=-1;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Остановить анимацию':'Запустить анимацию')};$('#speed').onclick=()=>{speed=speed===1?.5:speed===.5?1.5:1;$('#speed').textContent=speed+'×'};
document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));updateMaterials()});
const info=$('#info');$('#sources').onclick=$('#guideNav').onclick=()=>info.showModal();$('.close').onclick=()=>info.close();info.onclick=e=>{if(e.target===info){const r=info.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)info.close()}};$('#atlasNav').onclick=()=>$('.workspace').scrollIntoView({behavior:'smooth'});
let touchX=0;$('.lesson').addEventListener('touchstart',e=>touchX=e.touches[0].clientX,{passive:true});$('.lesson').addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>65)choose(index+(d<0?1:-1))},{passive:true});document.addEventListener('keydown',e=>{if(info.open||['INPUT','BUTTON'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')choose(index+1);if(e.key==='ArrowLeft')choose(index-1)});
function updateMaterials(){const m=movements[index];for(const mesh of meshes){const p=mesh.userData.part;mesh.visible=layer==='all'||p.system===layer||(layer==='muscular'&&p.system==='skeletal');const mat=mesh.material;const active=m.active.test(p.name);mat.color.set(p.system==='skeletal'?'#c5bf9f':p.system==='connective'?'#ded3b4':active?'#ec8763':'#9c5947');mat.emissive.set(active&&p.system==='muscular'?'#522112':'#000000');mat.opacity=layer==='muscular'&&p.system==='skeletal'?.8:1;mat.transparent=mat.opacity<1;}}
// Rigid segment animation: reference meshes retain their original shapes.
// This is an educational illustration; no claim of soft-tissue simulation.
const pivot=new T.Vector3(),rot=new T.Euler();
function transform(mesh,x,y,z,rx,rz=0){pivot.set(x,y,z);rot.set(rx,0,rz);mesh.position.copy(pivot).sub(pivot.clone().applyEuler(rot));mesh.rotation.copy(rot)}
function pose(){if(!ready)return;const a=amount*movements[index].max*Math.PI/180;for(const mesh of meshes){mesh.position.set(0,0,0);mesh.rotation.set(0,0,0);const c=mesh.userData.center,p=mesh.userData.part;const side=Math.sign(c.x)||1;
 if(index===0&&Math.abs(c.x)>.205&&c.y<1.115&&c.y>.68)transform(mesh,side*.225,1.11,-.02,-a);
 if(index===1&&Math.abs(c.x)>.145&&c.y<1.4&&c.y>.68)transform(mesh,side*.16,1.405,-.025,0,side*a);
 if(index===2&&Math.abs(c.x)<.18&&c.y<.455)transform(mesh,side*.08,.465,-.025,a);
 if(index===3&&c.y<.115)transform(mesh,side*.075,.09,-.025,a);
}}
function reset(){camera.position.set(.27,1.03,2.5);controls.target.set(0,.85,0);controls.update()}$('#reset').onclick=()=>{if(controls)reset()};
async function init(){try{renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.4;$('#canvas').appendChild(renderer.domElement);scene=new T.Scene();camera=new T.PerspectiveCamera(38,1,.01,30);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=.5;controls.maxDistance=4;controls.maxPolarAngle=Math.PI*.93;controls.enablePan=true;reset();scene.add(new T.HemisphereLight(0xf6f8d9,0x28372d,2.2));const key=new T.DirectionalLight(0xfff0d2,3.2);key.position.set(-2,3,4);scene.add(key);const rim=new T.DirectionalLight(0xc6e2ce,2);rim.position.set(2,1,-2);scene.add(rim);
const ring=new T.Mesh(new T.RingGeometry(.3,.302,100),new T.MeshBasicMaterial({color:0x77876b,transparent:true,opacity:.3,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=-.012;scene.add(ring);
const responses=await Promise.all([fetch('assets/body.json'),fetch('assets/body.bin')]);if(responses.some(r=>!r.ok))throw Error('Не удалось загрузить геометрию');const [parts,buf]=await Promise.all([responses[0].json(),responses[1].arrayBuffer()]);
for(const p of parts){const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(new Float32Array(buf,p.positions,p.vertexCount*3),3));g.setAttribute('normal',new T.BufferAttribute(new Int16Array(buf,p.normals,p.vertexCount*3),3,true));g.setIndex(new T.BufferAttribute(new Uint32Array(buf,p.indices,p.indexCount),1));g.computeBoundingSphere();const mat=new T.MeshStandardMaterial({roughness:.7,metalness:.02,side:T.DoubleSide});const mesh=new T.Mesh(g,mat);mesh.userData.part=p;mesh.userData.center=new T.Vector3(...p.bounds[0]).add(new T.Vector3(...p.bounds[1])).multiplyScalar(.5);meshes.push(mesh);scene.add(mesh)}
$('#structureCount').textContent=parts.length.toLocaleString('ru');$('#loading').style.display='none';ready=true;updateMaterials();pose();
const resize=()=>{const r=$('#canvas').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe($('#canvas'));resize();
const ray=new T.Raycaster(),mouse=new T.Vector2();let down=[0,0];renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(meshes.filter(m=>m.visible))[0];if(hit){$('#selection').hidden=false;$('#selection b').textContent=hit.object.userData.part.name}});$('#selection button').onclick=()=>$('#selection').hidden=true;
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;if(playing){amount+=direction*dt*.25*speed;if(amount>=1){amount=1;direction=-1}if(amount<=0){amount=0;direction=1;if(!$('#loop').checked){playing=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Запустить анимацию')}}updateProgress();pose()}controls.update();renderer.render(scene,camera)}requestAnimationFrame(frame);
}catch(e){console.error(e);$('#loading').innerHTML='<b>3D-модель недоступна</b><span>Проверьте поддержку WebGL и запустите сайт через HTTP-сервер.</span><button id="retry">Повторить загрузку ↻</button>';$('#retry').onclick=()=>location.reload()}}
renderLesson();init();
